"""Read data statements from the SQL dumps generated by the backup tools."""

import re


INSERT_START = re.compile(r'^INSERT\s+INTO\s+', re.IGNORECASE)
LEGACY_USER_INSERT = re.compile(r'^(INSERT\s+INTO\s+`users`)(\s+VALUES\b)', re.IGNORECASE)
USER_DEFINITION = re.compile(r'^CREATE TABLE `users` \(\n(.*?)^\)', re.IGNORECASE | re.MULTILINE | re.DOTALL)


def read_backup_inserts(dump):
    """Restore legacy positional user inserts using the schema recorded in the dump."""
    statements = []
    pending = []
    user_columns = None
    for line in dump.splitlines():
        if not pending:
            line = line.lstrip()
            if not INSERT_START.match(line):
                continue
            if LEGACY_USER_INSERT.match(line):
                if user_columns is None:
                    definition = USER_DEFINITION.search(dump)
                    columns = re.findall(r'^\s+`([a-zA-Z0-9_]+)`\s', definition[1], re.MULTILINE) if definition else []
                    if not columns:
                        raise ValueError('This backup omits the column names for users.')
                    user_columns = ', '.join(f'`{column}`' for column in columns)
                line = LEGACY_USER_INSERT.sub(rf'\g<1> ({user_columns})\g<2>', line, count=1)
        pending.append(line)
        if line.rstrip().endswith(';'):
            statements.append('\n'.join(pending))
            pending.clear()
    if pending or not statements:
        raise ValueError('The backup does not contain complete data statements.')
    return statements
